@props(['post'])

@auth
    <!-- Clap Section -->
    <div x-data="{
        hasClapped: {{ auth()->user()->hasClapped($post) ? 'true' : 'false' }},
        count: {{ $post->claps()->count() }},
        clap() {
            axios.post('/clap/{{ $post->id }}')
                .then(response => {
                    this.hasClapped = !this.hasClapped;
                    this.count = response.data.clapsCount;
                    // Show toast notification
                    if (window.showToast) {
                        window.showToast(response.data.message, 'success');
                    }
                })
                .catch(error => {
                    console.error(error);
                });
        }
    }" class="mt-8 p-4 border-t border-b">
        <button class="flex gap-2 text-gray-500 hover:text-gray-900" @click="clap()" :title="hasClapped ? 'Batalkan clap pada post ini' : 'Berikan clap pada post ini'">
